import { ThreeDMarquee } from "@/components/ui/3d-marquee";
import { Heart } from "lucide-react";

/**
 * Screens of the app itself (public/login-marquee, regenerated by
 * e2e/marquee-screenshots.spec.ts after visible UI changes). The marquee
 * splits the list into 4 columns of 9: light and dark alternate like a
 * checkerboard and no screen touches its own other theme.
 */
const COLUMNS = [
  ["inventory-light", "items-dark", "categories-light", "orders-dark", "pos-item-light", "history-dark", "tracking-light", "item-dark", "order-detail-light"],
  ["pos-dark", "store-light", "addons-dark", "settings-light", "overview-dark", "addons-light", "members-dark", "cart-light", "inventory-dark"],
  ["items-light", "order-detail-dark", "members-light", "pos-item-dark", "item-light", "tracking-dark", "overview-light", "store-dark", "menu-light"],
  ["kitchen-dark", "orders-light", "settings-dark", "pos-light", "menu-dark", "history-light", "cart-dark", "kitchen-light", "categories-dark"],
];
const images = COLUMNS.flat().map((name) => `/login-marquee/${name}.webp`);

export default function AnimatedBackground() {
  return (
    <div className="relative hidden h-full flex-col bg-muted p-6 lg:flex border-r">
      <div className="absolute inset-0 -top-30 bg-primary overflow-hidden">
        <ThreeDMarquee images={images} className="h-auto" />
      </div>
      {/* Keeps the name and the credit readable over light screenshots. */}
      <div aria-hidden className="absolute inset-x-0 top-0 z-10 h-28 bg-gradient-to-b from-primary to-transparent" />
      <div aria-hidden className="absolute inset-x-0 bottom-0 z-10 h-28 bg-gradient-to-t from-primary to-transparent" />
      <div className="relative z-20 flex justify-end items-center text-lg font-medium text-primary-foreground">
        Menu App
      </div>
      <div className="relative z-20 mt-auto text-primary-foreground text-sm flex items-center gap-1">
        Feito com <Heart className="size-4 fill-primary-foreground" /> por{" "}
        <a
          href="https://github.com/dollyzn"
          target="_blank"
          className="underline"
        >
          dollyzn
        </a>
      </div>
    </div>
  );
}
